class stringx {
public:
    char *data;
    int length;
    stringx(const char *, int = -1);
    stringx(const stringx &);
    ~stringx();
    stringx &operator=(const stringx &);
};

extern "C" int sprintf(char *, const char *, ...);
extern stringx logbook_months[4] __asm__("logbook_months");
__asm__(".equ logbook_months,0x003E6650");

class LogbookFrontEnd {
public:
    stringx GetDate(int);
};

stringx LogbookFrontEnd::GetDate(int note)
{
    stringx result = "";
    int max_days[] = { 31, 30, 31, 31 };
    int month = 0;
    int day = 10;
    for(int i = 0; i < 32; i++)
    {
        if(i == note)
        {
            char date[32];
            sprintf(date, logbook_months[month].data, day+1);
            result = stringx(date);
            return result;
        }

        day += 3;
        if(day >= max_days[month])
        {
            day = 0;
            month++;
        }
    }
    return result;
}
